好きなアニメや絵本、冬のスイーツを紹介し合い、宇宙旅行の話から、みんなで宇宙で百万人ライブをする夢へと想像を広げた。
練習後に二人でスターバックスへ行ったことを明かし、同じカスタムの抹茶ティーラテを飲みながら、今度は洋服を選びに行く計画を話した。
